            72: ft25_i = v[144:0];
            73: ft26_i = v[1:0];
            74: ft27_i = v[1:0];
            75: ft28_i = v[128:0];
            76: ft29_i = v[128:0];
            77: ft2_i = v[48:0];
            78: ft30_i = v[1:0];
            79: ft31_i = v[1:0];
            80: ft3_i = v[48:0];
            81: ft4_i = v[256:0];
            82: ft5_i = v[1118:0];
            83: ft6_i = v[1118:0];
            84: ft7_i = v[128:0];
            85: ft8_i = v[128:0];
            86: ft9_i = v[28:0];
            default: $fatal(1, "bad input index %0d", idx);
        endcase
    endtask
    initial begin : replay
        string f; integer fd, idx, n = 0; longint tps, until = 0; bit [8191:0] v; realtime now;
        if (!$value$plusargs("REP=%s", f)) $fatal(1, "+REP=<record> required");
        void'($value$plusargs("UNTIL=%d", until));
        fd = $fopen(f, "r"); if (fd == 0) $fatal(1, "cannot open %s", f);
        while ($fscanf(fd, "%d %d %h", tps, idx, v) == 3) begin
            if (until > 0 && tps > until) break;
            now = tps / 1000.0 + 0.001;
            if (now > $realtime) #(now - $realtime);
            apply(idx, v); n++;
        end
        $display("PARTREP done %0d changes, t %0t core_cyc %0d", n, $realtime, core_cyc);
        #10 $finish;
    end
endmodule
